/**
 * Verify the AI play flow now builds a usable queue (single requested song →
 * album/artist/library context) and auto-advance works afterwards.
 * Usage: node scripts/diag-ai-queue.mjs
 */
const PORT = 9222
const list = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
const page = list.find((t) => t.type === 'page' && t.url.includes('localhost:5173') && !t.url.includes('#mini'))
if (!page) throw new Error('dev page not found')

const ws = new WebSocket(page.webSocketDebuggerUrl)
await new Promise((resolve, reject) => {
  ws.onopen = resolve
  ws.onerror = reject
})
let id = 0
const pending = new Map()
ws.onmessage = (evMsg) => {
  const m = JSON.parse(evMsg.data)
  if (m.id && pending.has(m.id)) {
    pending.get(m.id)(m.result)
    pending.delete(m.id)
  }
}
const raw = (method, params = {}) =>
  new Promise((resolve) => {
    const i = ++id
    pending.set(i, resolve)
    ws.send(JSON.stringify({ id: i, method, params }))
  })
const ev = async (expr) => {
  const r = await raw('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true })
  if (r?.exceptionDetails) return 'EXC: ' + (r.exceptionDetails.exception?.description ?? '')
  return r?.result?.value ?? r
}

const out = JSON.parse(
  await ev(`(async () => {
    const sleep = (ms) => new Promise(r => setTimeout(r, ms))
    await window.api.settingsSetApi({ baseURL: 'http://127.0.0.1:9999/v1', model: 'deepseek-v4-flash', apiKey: 'sk-x' })
    const C = window.__nebula.chat
    await C.getState().load()
    C.getState().setDraft('播放一首歌')
    await C.getState().send()
    await sleep(7000)
    const p = window.__nebula.player.getState()
    const last = C.getState().messages[C.getState().messages.length - 1]
    return JSON.stringify({
      queueLen: p.queue.length,
      current: p.current?.title ?? null,
      isPlaying: p.isPlaying,
      mode: p.mode,
      chips: last?.chips ?? [],
      reply: (last?.content ?? '').slice(0, 40)
    })
  })()`)
)
console.log('AI play flow:', JSON.stringify(out, null, 2))

// let the shortest queue member finish and confirm auto-advance
await ev(`(async () => {
  const p = window.__nebula.player.getState()
  p.seek(Math.max(0, (p.duration || 5) - 1.2))
  return 'near-end'
})()`)
await new Promise((r) => setTimeout(r, 6000))
console.log(
  'after end:',
  await ev(`JSON.stringify({
    current: window.__nebula.player.getState().current?.title,
    index: window.__nebula.player.getState().index,
    isPlaying: window.__nebula.player.getState().isPlaying
  })`)
)

ws.close()
setTimeout(() => process.exit(0), 300)

/**
 * Rescan + verify an artist has 2+ covers, then screenshot the artists page.
 * Usage: node scripts/diag-artist-badge.mjs
 */
import { writeFile } from 'fs/promises'

const PORT = 9222
const res = await fetch(`http://127.0.0.1:${PORT}/json`)
const list = await res.json()
const page = list.find((t) => t.type === 'page' && t.url.includes('localhost:5173'))
if (!page) throw new Error('dev page not found')

const ws = new WebSocket(page.webSocketDebuggerUrl)
await new Promise((resolve, reject) => {
  ws.onopen = resolve
  ws.onerror = reject
})
let id = 0
const pending = new Map()
ws.onmessage = (evMsg) => {
  const m = JSON.parse(evMsg.data)
  if (m.id && pending.has(m.id)) {
    pending.get(m.id)(m.result)
    pending.delete(m.id)
  }
}
const raw = (method, params = {}) =>
  new Promise((resolve) => {
    const i = ++id
    pending.set(i, resolve)
    ws.send(JSON.stringify({ id: i, method, params }))
  })
const ev = async (expr) => {
  const r = await raw('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true })
  return r?.result?.value ?? r
}

const rawInfo = await ev(`(async () => {
  try {
    const res = await window.__nebula.library.getState().scan(['C:\\\\博830\\\\vibecoding\\\\nebula-player\\\\.devdata\\\\test-music'])
    const lib = await window.api.libraryGet()
    return JSON.stringify({ scan: res, tracks: lib.tracks.map(t => ({ title: t.title, artist: t.artist, cover: !!t.coverPath })) })
  } catch (e) {
    return JSON.stringify({ err: String(e) })
  }
})()`)
if (typeof rawInfo !== 'string') {
  console.error('unexpected evaluate result:', JSON.stringify(rawInfo))
  ws.close()
  process.exit(1)
}
const info = JSON.parse(rawInfo)
console.log(JSON.stringify(info, null, 2))

await new Promise((r) => setTimeout(r, 1400))
const shot = await raw('Page.captureScreenshot', { format: 'png' })
await writeFile('.devdata/shot-artists-badge.png', Buffer.from(shot.data, 'base64'))
console.log('saved')
ws.close()
process.exit(0)

/**
 * Probe: why does ensureGraph fail? Try fresh ctx + MediaElementSource attach
 * on the engine's current audio element, report exact behavior.
 * Usage: node scripts/diag-attach.mjs
 */
const PORT = 9222
const res = await fetch(`http://127.0.0.1:${PORT}/json`)
const list = await res.json()
const page = list.find((t) => t.type === 'page' && t.url.includes('localhost:5173'))
if (!page) throw new Error('dev page not found')

const ws = new WebSocket(page.webSocketDebuggerUrl)
await new Promise((resolve, reject) => {
  ws.onopen = resolve
  ws.onerror = reject
})
let id = 0
const pending = new Map()
ws.onmessage = (ev) => {
  const m = JSON.parse(ev.data)
  if (m.id && pending.has(m.id)) {
    pending.get(m.id)(m.result)
    pending.delete(m.id)
  }
}
const ev = (expr) =>
  new Promise((resolve) => {
    const i = ++id
    pending.set(i, resolve)
    ws.send(
      JSON.stringify({
        id: i,
        method: 'Runtime.evaluate',
        params: { expression: expr, awaitPromise: true, returnByValue: true }
      })
    )
  })

const out = await ev(`(async () => {
  const out = {}
  const a = document.querySelector('audio')
  out.foundElement = !!a
  try {
    const c = new AudioContext()
    out.ctxCreate = { ok: true, state: c.state }
    try {
      c.createMediaElementSource(a)
      out.attach = 'ok'
    } catch (e) { out.attach = 'THROW: ' + String(e) }
    await c.close()
  } catch (e) { out.ctxCreate = { ok: false, err: String(e) } }
  return JSON.stringify(out)
})()`)
console.log(out.result.value)
ws.close()
process.exit(0)

/**
 * Live audio diagnostics via CDP (dev app must be running).
 * Usage: node scripts/diag-audio.mjs
 */
const PORT = 9222

async function connect() {
  const res = await fetch(`http://127.0.0.1:${PORT}/json`)
  const list = await res.json()
  const page = list.find((t) => t.type === 'page' && t.url.includes('localhost:5173'))
  if (!page) throw new Error('dev page not found')
  const ws = new WebSocket(page.webSocketDebuggerUrl)
  await new Promise((resolve, reject) => {
    ws.onopen = resolve
    ws.onerror = reject
  })
  let seq = 0
  const pending = new Map()
  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data)
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id)
      pending.delete(msg.id)
      msg.error ? reject(new Error(msg.error.message)) : resolve(msg.result)
    }
  }
  const evaluate = (expression, awaitPromise = true) =>
    new Promise((resolve, reject) => {
      const id = ++seq
      pending.set(id, { resolve, reject })
      ws.send(
        JSON.stringify({
          id,
          method: 'Runtime.evaluate',
          params: { expression, awaitPromise, returnByValue: true }
        })
      )
    }).then((r) => {
      if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description ?? 'page exception')
      return r.result?.value
    })
  return { ws, evaluate }
}

const { ws, evaluate } = await connect()

// 1) play first track via store
await evaluate(`(async () => {
  const lib = await window.api.libraryGet()
  await window.__nebula.player.getState().playTracks(lib.tracks, 0)
  return 'playing started'
})()`)
await new Promise((r) => setTimeout(r, 2500))

const result = JSON.parse(
  await evaluate(`(() => {
    const a = document.querySelector('audio')
    let freshCtx = null
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext
      freshCtx = new Ctx()
      rawFresh = freshCtx.state
    } catch (e) { rawFresh = 'ERR:' + String(e) }
    var rawFresh
    if (freshCtx) freshCtx.close()
    const raw = {}
    try {
      const ai = a
      raw.el = {
        paused: ai.paused, muted: ai.muted, volume: ai.volume,
        currentTime: ai.currentTime, duration: ai.duration,
        readyState: ai.readyState, networkState: ai.networkState,
        src: (ai.currentSrc || '').slice(0, 40),
        error: ai.error ? { code: ai.error.code, msg: ai.error.message } : null
      }
    } catch (e) { raw.el = 'ERR:' + String(e) }
    return JSON.stringify({ element: raw.el, freshContextState: rawFresh })
  })()`)
)

console.log(JSON.stringify(result, null, 2))
ws.close()
process.exit(0)

/**
 * Test auto-advance: play a 2-track queue, wait past the first track's end,
 * report whether the player advanced on its own. Also test a 1-track queue.
 * Usage: node scripts/diag-autonext.mjs
 */
const PORT = 9222
const list = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
const page = list.find((t) => t.type === 'page' && t.url.includes('localhost:5173') && !t.url.includes('#mini'))
if (!page) throw new Error('dev page not found')

const ws = new WebSocket(page.webSocketDebuggerUrl)
await new Promise((resolve, reject) => {
  ws.onopen = resolve
  ws.onerror = reject
})
let id = 0
const pending = new Map()
ws.onmessage = (evMsg) => {
  const m = JSON.parse(evMsg.data)
  if (m.id && pending.has(m.id)) {
    pending.get(m.id)(m.result)
    pending.delete(m.id)
  }
}
const raw = (method, params = {}) =>
  new Promise((resolve) => {
    const i = ++id
    pending.set(i, resolve)
    ws.send(JSON.stringify({ id: i, method, params }))
  })
const ev = async (expr) => {
  const r = await raw('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true })
  if (r?.exceptionDetails) return 'EXC: ' + (r.exceptionDetails.exception?.description ?? 'unknown')
  return r?.result?.value ?? r
}

// instrument: record ended events on the engine
console.log(
  'instrument:',
  await ev(`(async () => {
    const N = window.__nebula
    window.__endedLog = []
    N.engine.on('ended', () => window.__endedLog.push(Date.now()))
    return 'ok'
  })()`)
)

// --- 2-track queue: first track is 5s (song-c), second 6s (SongB) ---
console.log(
  'two-track start:',
  await ev(`(async () => {
    const lib = await window.api.libraryGet()
    const two = lib.tracks.filter(t => t.duration <= 8).slice(0, 2)
    const N = window.__nebula.player.getState()
    await N.playTracks(two, 0)
    return JSON.stringify({ queue: two.map(t => t.title), durations: two.map(t => t.duration) })
  })()`)
)
await new Promise((r) => setTimeout(r, 9000))
console.log(
  'two-track after 9s:',
  await ev(`JSON.stringify({
    current: window.__nebula.player.getState().current?.title,
    index: window.__nebula.player.getState().index,
    isPlaying: window.__nebula.player.getState().isPlaying,
    endedEvents: window.__endedLog.length,
    engineMode: window.__nebula.engine.getMode()
  })`)
)

// --- 1-track queue ---
console.log(
  'one-track start:',
  await ev(`(async () => {
    const lib = await window.api.libraryGet()
    const one = lib.tracks.filter(t => t.duration <= 5)[0]
    window.__nebula.player.getState().playTracks([one], 0)
    return JSON.stringify({ track: one.title, duration: one.duration })
  })()`)
)
await new Promise((r) => setTimeout(r, 9000))
console.log(
  'one-track after 9s:',
  await ev(`JSON.stringify({
    current: window.__nebula.player.getState().current?.title,
    isPlaying: window.__nebula.player.getState().isPlaying,
    time: Math.round(window.__nebula.player.getState().currentTime),
    endedEvents: window.__endedLog.length
  })`)
)

ws.close()
setTimeout(() => process.exit(0), 300)

