/**
 * E2E smoke driver for the running dev app (CDP on 127.0.0.1:9222).
 * Usage: node scripts/e2e.mjs scan|play|chat|all [testMusicDir]
 */
import { readFile } from 'fs/promises'

const PORT = 9222
const testMusic = process.argv[3] ?? 'C:\\博830\\vibecoding\\nebula-player\\.devdata\\test-music'
const mode = process.argv[2] ?? 'all'

async function targets() {
  const res = await fetch(`http://127.0.0.1:${PORT}/json`)
  return res.json()
}

async function main() {
  const list = await targets()
  const page = list.find((t) => t.type === 'page' && t.url.includes('localhost:5173'))
  if (!page) throw new Error('dev page not found: ' + JSON.stringify(list.map((t) => ({ url: t.url, type: t.type }))))

  const ws = new WebSocket(page.webSocketDebuggerUrl)
  await new Promise((resolve, reject) => {
    ws.onopen = resolve
    ws.onerror = reject
  })

  let seq = 0
  const pending = new Map()
  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data)
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id)
      pending.delete(msg.id)
      if (msg.error) reject(new Error(msg.error.message))
      else resolve(msg.result)
    }
  }

  const evaluate = (expression, awaitPromise = true) =>
    new Promise((resolve, reject) => {
      const id = ++seq
      pending.set(id, { resolve, reject })
      ws.send(
        JSON.stringify({
          id,
          method: 'Runtime.evaluate',
          params: { expression, awaitPromise, returnByValue: true }
        })
      )
    }).then((r) => {
      if (r.exceptionDetails) {
        throw new Error('page exception: ' + JSON.stringify(r.exceptionDetails.exception?.description ?? r.exceptionDetails))
      }
      return r.result?.value
    })

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

  const out = {}

  if (mode === 'scan' || mode === 'all') {
    out.scan = JSON.parse(
      await evaluate(`(async () => {
        const T = ${JSON.stringify(testMusic)}
        const scanRes = await window.api.libraryScan([T])
        await window.__nebula.library.getState().load()
        const lib = await window.api.libraryGet()
        return JSON.stringify({
          scan: scanRes,
          tracks: lib.tracks.map(t => ({title: t.title, artist: t.artist, album: t.album, genre: t.genre, ext: t.ext, duration: t.duration, folderName: t.folderName, cover: !!t.coverPath}))
        })
      })()`)
    )
  }

  if (mode === 'play' || mode === 'all') {
    out.play = JSON.parse(
      await evaluate(`(async () => {
        const N = window.__nebula
        const lib = await window.api.libraryGet()
        const tracks = lib.tracks
        if (!tracks.length) return JSON.stringify({error: 'no tracks'})
        await N.player.getState().playTracks(tracks, 0)
        await new Promise(r => setTimeout(r, 1500))
        const p = N.player.getState()
        const mid = { current: p.current?.title, isPlaying: p.isPlaying, loading: p.isLoading, time: Math.round(p.currentTime), duration: Math.round(p.duration), mode: p.mode }
        p.seek(p.duration / 2)
        await new Promise(r => setTimeout(r, 600))
        const after = N.player.getState()
        p.setVolume(0.3)
        p.setMode('shuffle')
        p.next()
        await new Promise(r => setTimeout(r, 1200))
        const nxt = N.player.getState()
        p.prev()
        await new Promise(r => setTimeout(r, 800))
        const prv = N.player.getState()
        p.toggle()
        await new Promise(r => setTimeout(r, 300))
        const toggled = N.player.getState()
        p.toggle()
        return JSON.stringify({
          first: mid,
          seekTime: Math.round(after.currentTime),
          nextTitle: nxt.current?.title,
          prevTitle: prv.current?.title,
          pausedAfterToggle: !toggled.isPlaying,
          volume: after.volume,
          mode: after.mode
        })
      })()`)
    )
  }

  if (mode === 'playlists' || mode === 'all') {
    out.playlists = JSON.parse(
      await evaluate(`(async () => {
        const N = window.__nebula
        const lib = await window.api.libraryGet()
        const pl = N.playlists.getState()
        const created = pl.create('E2E测试歌单')
        pl.addTracks(created.id, lib.tracks.map(t => t.id))
        const fav1 = pl.toggleFavorite(lib.tracks[0].id)
        const fav2 = pl.toggleFavorite(lib.tracks[0].id)
        const state = N.playlists.getState()
        await new Promise(r => setTimeout(r, 600))
        return JSON.stringify({
          created: created.name,
          count: state.playlists.find(x => x.id === created.id)?.trackIds.length,
          favOn: fav1, favOff: fav2,
          favCount: state.playlists.find(x => x.builtin === 'favorites')?.trackIds.length ?? -1,
          persisted: (await window.api.playlistLoad()).playlists.length
        })
      })()`)
    )
  }

  if (mode === 'chat' || mode === 'all') {
    out.chat = JSON.parse(
      await evaluate(`(async () => {
        const C = window.__nebula.chat
        C.getState().setDraft('测试：暂停播放并介绍一下爵士乐')
        await C.getState().send()
        await new Promise(r => setTimeout(r, 5000))
        const st = C.getState()
        const last = st.messages[st.messages.length - 1]
        return JSON.stringify({ busy: st.busy, lastRole: last?.role, lastContent: (last?.content ?? '').slice(0, 80) })
      })()`)
    )
  }

  if (mode === 'ai') {
    // configure the mock endpoint then run a real chat round (tool calling)
    out.ai = JSON.parse(
      await evaluate(`(async () => {
        await window.api.settingsSetApi({ baseURL: 'http://127.0.0.1:9999/v1', model: 'mock-model', apiKey: 'sk-mock' })
        const conf = await window.api.settingsGet()
        const test = await window.api.settingsTestApi()
        const C = window.__nebula.chat
        await C.getState().load()
        C.getState().setDraft('帮我找一下歌曲并播放')
        await C.getState().send()
        await new Promise(r => setTimeout(r, 6000))
        const st = C.getState()
        const last = st.messages[st.messages.length - 1]
        return JSON.stringify({
          configured: { baseURL: conf.api.baseURL, model: conf.api.model, hasKey: conf.api.hasKey },
          testOk: test.ok,
          busy: st.busy,
          chips: last?.chips ?? [],
          lastContent: (last?.content ?? '').slice(0, 60),
          totalMessages: st.messages.length
        })
      })()`)
    )
  }

  if (mode === 'clean') {
    out.clean = JSON.parse(
      await evaluate(`(async () => {
        await window.api.settingsSetApi({ baseURL: '', model: '', apiKey: '' })
        const N = window.__nebula
        const st = N.playlists.getState()
        for (const p of st.playlists.filter(p => !p.builtin && p.name.startsWith('E2E'))) st.remove(p.id)
        N.chat.setState({ messages: [], bubbles: [] })
        await window.api.chatSave([])
        return JSON.stringify({ ok: true })
      })()`)
    )
  }

  if (mode === 'state') {
    out.state = JSON.parse(
      await evaluate(`(async () => {
        const raw = localStorage.getItem('nebula.player.state')
        const st = window.__nebula.player.getState()
        return JSON.stringify({ persisted: raw ? JSON.parse(raw) : null, current: st.current?.title ?? null, mode: st.mode, volume: st.volume })
      })()`)
    )
  }

  console.log(JSON.stringify(out, null, 2))
  ws.close()

  // cleanup created artifacts (run with mode=playlists to keep them)
  if (mode === 'all') {
    await evaluate(
      `(async () => {
        const N = window.__nebula
        const st = N.playlists.getState()
        for (const p of st.playlists.filter(p => !p.builtin && p.name.startsWith('E2E'))) st.remove(p.id)
        await window.api.chatSave([])
        N.chat.setState({ messages: [], bubbles: [] })
        return 'cleaned'
      })()`
    ).catch(() => {})
  }
  await sleep(300)
  process.exit(0)
}

main().catch((err) => {
  console.error('E2E failed:', err.message)
  process.exit(1)
})

/**
 * Mock OpenAI-compatible server for E2E testing of the AI pipeline.
 * GET /v1/models       → ok
 * POST /v1/chat/completions → if last message role==='tool' → final text
 *                             else → tool_calls (search_music)
 * Usage: node scripts/mock-llm.mjs [port]
 */
import { createServer } from 'http'

const port = Number(process.argv[2] ?? 9999)

const sse = (res, chunks) => {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    Connection: 'keep-alive'
  })
  for (const c of chunks) res.write(`data: ${JSON.stringify(c)}\n\n`)
  res.write('data: [DONE]\n\n')
  res.end()
}

const toolCallChunk = {
  choices: [
    {
      delta: {
        tool_calls: [
          {
            index: 0,
            id: 'call_mock_1',
            type: 'function',
            function: {
              name: 'search_music',
              arguments: '{"query":"歌","limit":3}'
            }
          }
        ]
      },
      finish_reason: null
    }
  ]
}
const toolCallDone = { choices: [{ delta: {}, finish_reason: 'tool_calls' }] }
const textChunk = (t) => ({ choices: [{ delta: { content: t }, finish_reason: null }] })
const textDone = { choices: [{ delta: {}, finish_reason: 'stop' }] }

const SUPPORTED = ['deepseek-v4-pro', 'deepseek-v4-flash', 'deepseek-v4-flash-vision-exp']

createServer((req, res) => {
  if (req.method === 'GET' && req.url === '/v1/models') {
    res.writeHead(200, { 'Content-Type': 'application/json' })
    res.end(
      JSON.stringify({
        object: 'list',
        data: SUPPORTED.map((id) => ({ id }))
      })
    )
    return
  }
  if (req.method === 'POST' && req.url === '/v1/chat/completions') {
    let body = ''
    req.on('data', (d) => (body += d))
    req.on('end', () => {
      const json = JSON.parse(body || '{}')
      const messages = json.messages ?? []
      const last = messages[messages.length - 1]
      // validate the model id — mimic a gateway 400 for unsupported model
      const model = json.model ?? ''
      if (!SUPPORTED.includes(model)) {
        res.writeHead(400, { 'Content-Type': 'application/json' })
        res.end(
          JSON.stringify({
            error: {
              message: `The supported API model names are ${SUPPORTED.join(', ')}, but you passed ${model}.`
            }
          })
        )
        return
      }
      // strict tool-sequence validation (mimics OpenAI/DeepSeek)
      const msgs = json.messages ?? []
      const toolIds = new Set()
      let lastAssistantCalls = []
      for (const m of msgs) {
        if (m.role === 'assistant' && m.tool_calls) lastAssistantCalls = m.tool_calls
        if (m.role === 'tool') {
          if (!lastAssistantCalls.some((tc) => tc.id === m.tool_call_id)) {
            res.writeHead(400, { 'Content-Type': 'application/json' })
            res.end(
              JSON.stringify({
                error: { message: `Messages with role 'tool' must be a response to a preceding message with 'tool_calls'` }
              })
            )
            return
          }
          void toolIds
        }
      }
      try {
        const lastUser = [...messages].reverse().find((m) => m.role === 'user')
        const wantsRecommend = String(lastUser?.content ?? '').includes('推荐')
        if (last?.role === 'tool') {
          const content = String(last.content ?? '')
          if (content.includes('"tracks"')) {
            // search result → now ask the app to play the first match
            let id = 'unknown'
            try {
              const parsed = JSON.parse(content)
              id = parsed.tracks?.[0]?.id ?? 'unknown'
            } catch {
              // ignore
            }
            const playCall = {
              choices: [
                {
                  delta: {
                    tool_calls: [
                      {
                        index: 0,
                        id: 'call_mock_play',
                        type: 'function',
                        function: { name: 'play_tracks', arguments: JSON.stringify({ ids: [id], start_index: 0 }) }
                      }
                    ]
                  },
                  finish_reason: null
                }
              ]
            }
            sse(res, [playCall, toolCallDone])
          } else if (content.includes('"recommendations"')) {
            sse(res, [textChunk('根据你的口味，我最推荐以下几首（理由见列表）。'), textDone])
          } else {
            sse(res, [textChunk('好的，已经开始播放了。'), textDone])
          }
        } else if (wantsRecommend) {
          const recCall = {
            choices: [
              {
                delta: {
                  tool_calls: [
                    {
                      index: 0,
                      id: 'call_mock_rec',
                      type: 'function',
                      function: { name: 'recommend_music', arguments: JSON.stringify({ limit: 5 }) }
                    }
                  ]
                },
                finish_reason: null
              }
            ]
          }
          sse(res, [recCall, toolCallDone])
        } else {
          sse(res, [toolCallChunk, toolCallDone])
        }
      } catch (err) {
        res.writeHead(500)
        res.end(String(err))
      }
    })
    return
  }
  res.writeHead(404)
  res.end('not found')
}).listen(port, '127.0.0.1', () => {
  console.log(`mock LLM listening on http://127.0.0.1:${port}/v1`)
})

/**
 * Local generic update feed for E2E: serves latest.yml (configurable version)
 * + the installer from dist. Usage: node scripts/update-server.mjs <port> <version>
 */
import { createServer } from 'http'
import { createHash } from 'crypto'
import { promises as fs } from 'fs'
import { dirname, join } from 'path'
import { fileURLToPath } from 'url'

const port = Number(process.argv[2] ?? 8888)
const version = process.argv[3] ?? '1.0.2'
const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const exeName = `nebula-player-${version}-setup.exe`
const srcExe = join(root, 'dist', 'nebula-player-1.0.0-setup.exe')

// prepare feed dir
const feedDir = join(root, '.devdata', 'update-feed')
await fs.mkdir(feedDir, { recursive: true })
const exePath = join(feedDir, exeName)
await fs.copyFile(srcExe, exePath)
const size = (await fs.stat(exePath)).size
const sha512 = createHash('sha512').update(await fs.readFile(exePath)).digest('base64')
const latest = {
  version,
  files: [{ url: exeName, sha512, size }],
  path: exeName,
  sha512,
  releaseDate: new Date().toISOString(),
  releaseName: `NEBULA ${version}`
}
await fs.writeFile(join(feedDir, 'latest.yml'), JSON.stringify(latest, null, 2), 'utf-8')
console.log(`feed ready: version ${version}, file ${size} bytes`)

createServer(async (req, res) => {
  const url = decodeURIComponent((req.url ?? '/').split('?')[0])
  const f = join(feedDir, url === '/' ? 'latest.yml' : url.replace(/^\//, ''))
  try {
    const data = await fs.readFile(f)
    const type = f.endsWith('.yml') ? 'text/yaml' : 'application/octet-stream'
    res.writeHead(200, { 'Content-Type': type, 'Content-Length': data.length })
    res.end(data)
  } catch {
    res.writeHead(404)
    res.end('not found')
  }
}).listen(port, '127.0.0.1', () => console.log(`update server on http://127.0.0.1:${port}/`))

