    const st = p.getState()
    const el = document.querySelector('audio')
    const elInfo = el
      ? { paused: el.paused, currentTime: el.currentTime, readyState: el.readyState, error: el.error ? { code: el.error.code, msg: el.error.message } : null, src: (el.currentSrc || '').slice(0, 30) }
      : { missing: true }
