    const d = ctx.getImageData(0, 0, w, h).data
    let nonBg = 0
    let max = 0
    for (let i = 0; i < d.length; i += 4) {
      const lum = d[i] + d[i + 1] + d[i + 2]
      if (lum > max) max = lum
      if (lum > 90) nonBg++
    }
    return { canvas: true, w, h, nonBgPixels: nonBg, maxLum: max }
  })())`)

